CREATE TABLE IF NOT EXISTS leads (id TEXT PRIMARY KEY,created_at TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('demo','contract')),name TEXT NOT NULL,company TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,plan TEXT NOT NULL,preferred_date TEXT,preferred_period TEXT,notes TEXT,status TEXT NOT NULL DEFAULT 'novo',notified INTEGER NOT NULL DEFAULT 0,notification_error TEXT);\nCREATE INDEX IF NOT EXISTS idx_leads_created_at ON leads(created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_leads_status ON leads(status);\n